import { pageOf } from '../src/pagination.mjs';
test('invalid pagination', () => {
  for (const [page, size] of [[0, 2], [1, 0], [1.5, 2], [1, 2.5], ['1', 2]]) {
    assert.throws(() => pageOf([], page, size), /Invalid pagination/);
  }
});
test('past the end', () => assert.deepEqual(pageOf([1, 2], 9, 2), []));

